effect.shader:
const float PI = 3.14159265;
const int N = 9;
const float OFF[9] = float[9](-4.0, -3.0, -2.0, -1.0, 0.0, 1.0, 2.0, 3.0, 4.0);
const float WT[9]  = float[9](0.028, 0.065, 0.121, 0.175, 0.198, 0.175, 0.121, 0.065, 0.028);

float mascaraFoco(vec2 uv) {
    float a = angle * PI / 180.0;
    vec2 n = vec2(-sin(a), cos(a));
    float d = abs(dot(uv - vec2(0.5, bandCenter), n));
    float meiaFaixa = bandWidth * 0.5;
    return smoothstep(meiaFaixa, meiaFaixa + falloff, d);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);
    float fora = mascaraFoco(acScreenNorm);
    float raio = radius * fora;
    if (raio <= 0.0 && acPass == 1) { fragColor = original; return; }

    vec2 direction = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = direction * acTexelSize * (raio * acEscalaDePixel);

    vec4 soma = vec4(0.0);
    for (int i = 0; i < N; i++) {
        vec2 uv = acScreenNorm + passo * OFF[i];
        vec4 c = (acPass == 0) ? texture(inputImg, uv) : texture(hblur, uv);
        soma += c * WT[i];
    }

    if (acPass == 0) {
        fragColor = soma;
    } else {
        fragColor = mix(original, soma, clamp(fora, 0.0, 1.0));
    }
}
